<script setup>
import {computed} from 'vue';
const props=defineProps({rows:{type:Array,default:()=>[]},series:{type:Array,default:()=>[]},kind:{default:'line'},labelKey:{default:'day'},label:String});
const colors=['#6366f1','#10b981','#38bdf8'];
const value=(r,s)=>Math.max(0,Number(r[s.key])||0);
const peak=computed(()=>Math.ceil(Math.max(4,...props.rows.map(r=>props.kind==='stacked'?props.series.reduce((n,s)=>n+value(r,s),0):Math.max(0,...props.series.map(s=>value(r,s)))))/4)*4);
const x=i=>42+i*574/Math.max(1,props.rows.length-1);const y=v=>208-v*178/peak.value;
const path=s=>props.rows.map((r,i)=>(i?'L':'M')+x(i)+','+y(value(r,s))).join(' ');
const ticks=computed(()=>[0,1,2,3,4].map(i=>Math.round(peak.value*i/4)));
const indices=computed(()=>[...new Set([0,Math.floor((props.rows.length-1)/2),props.rows.length-1])].filter(i=>i>=0));
const barWidth=computed(()=>574/Math.max(1,props.rows.length));
function base(row,i){return props.series.slice(0,i).reduce((n,s)=>n+value(row,s),0)}
</script>
<template><div class="analytics-chart"><svg viewBox="0 0 640 250" role="img" :aria-label="label"><title>{{label}}</title><g v-for="(tick,i) in ticks" :key="i"><line x1="42" x2="616" :y1="y(tick)" :y2="y(tick)" class="chart-grid"/><text x="32" :y="y(tick)+4" text-anchor="end">{{tick}}</text></g><template v-if="kind==='line'"><g v-for="(s,n) in series" :key="s.key"><path :d="path(s)" fill="none" :stroke="s.color||colors[n]" stroke-width="2.5" stroke-linejoin="round"/><circle v-for="(r,i) in rows" :key="i" :cx="x(i)" :cy="y(value(r,s))" r="3" :fill="s.color||colors[n]"><title>{{r[labelKey]}} · {{s.name}}: {{r[s.key]||0}}</title></circle></g></template><template v-else><g v-for="(r,i) in rows" :key="i"><rect v-for="(s,n) in series" :key="s.key" :x="42+i*barWidth+1" :y="y(base(r,n)+value(r,s))" :width="Math.max(1,barWidth-2)" :height="value(r,s)*178/peak" rx="2" :fill="s.color||colors[n]"><title>{{r[labelKey]}} · {{s.name}}: {{r[s.key]||0}}</title></rect></g></template><text v-for="i in indices" :key="i" :x="kind==='line'?x(i):42+(i+.5)*barWidth" y="234" :text-anchor="i===0?'start':i===rows.length-1?'end':'middle'">{{rows[i]?.[labelKey]}}</text></svg><div class="chart-legend"><span v-for="(s,i) in series" :key="s.key"><i :style="{background:s.color||colors[i]}"/>{{s.name}}</span></div><details class="chart-data"><summary>View chart data</summary><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th v-for="s in series" :key="s.key">{{s.name}}</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td>{{r[labelKey]}}</td><td v-for="s in series" :key="s.key">{{r[s.key]||0}}</td></tr></tbody></table></div></details></div></template>
<style scoped>.analytics-chart svg{width:100%;height:auto;display:block;overflow:visible}.analytics-chart text{fill:var(--muted,#64748b);font:11px system-ui}.chart-grid{stroke:var(--line,#e2e8f0);stroke-dasharray:3 5}.chart-legend{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;color:var(--muted,#64748b)}.chart-legend span{display:flex;align-items:center;gap:6px}.chart-legend i{width:9px;height:9px;border-radius:3px}.chart-data{font-size:12px;margin-top:14px}.chart-data .table-responsive{max-height:240px;margin-top:10px}</style>
